import{_ as r,l as s,o as e,c,v as l,p as d,x as o,d as i,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"slab 分配器","description":"","frontmatter":{"title":"slab 分配器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/slab-allocator.md","filePath":"cs/slab-allocator.md","lastUpdated":1789023840000}'),b={name:"cs/slab-allocator.md"};function p(_,a,m,u,B,E){const t=s("Mermaid");return e(),c("div",null,[a[1]||(a[1]=l('<h1 id="slab-分配器" tabindex="-1">slab 分配器 <a class="header-anchor" href="#slab-分配器" aria-label="Permalink to &quot;slab 分配器&quot;">​</a></h1><div class="epigraph"><p>同类内核对象从专用缓存里取：一页切成等长槽，构造函数只在首次填充时跑，避免每次从 buddy 要页再初始化。</p><footer>—— 据 Bonwick, The Slab Allocator, USENIX 1994；Love 对 SLAB/SLUB 的整理</footer></div><p><a href="/cs/buddy-allocator">上一课</a>给出页级块。inode、dentry、页表项描述符大小远小于一页，若每个对象 <code>alloc_pages(0)</code>，内碎片与初始化成本爆炸。<a href="/cs/vfs">VFS</a> 尚未讲，但对象缓存必须先存在。缺口是 <strong>slab</strong>：按类型的对象工厂，建立在 buddy 页之上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核分配有两个坏极端：全走 buddy（浪费），或一个全局字节堆（碎片与锁）。Bonwick 的方法：每种对象一个 cache，cache 持有若干 slab（一页或几页），slab 内空闲对象链表。分配 O(1) 取槽；释放回本 cache。着色（colouring）错开对象在页内偏移，减轻 Cache 行冲突。缺口不是用户 malloc 算法，而是内核里生命周期相似的对象。</p><p>本课不把 SLAB、SLOB、SLUB 三种实现做成对照表考试。</p><p><span class="marginnote">SLUB 简化了每 CPU 的部分数组，减少锁。对象可以有构造/析构。过大的对象仍直接走 buddy。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>kmem_cache_create</code> 登记大小与对齐。<code>kmem_cache_alloc</code> 从本 CPU 空闲槽取；没有则向 buddy 要一页填满对象。释放不立即还页，直到整页空闲或回收器收缩。与用户态对照：libc 的 arena 是进程私有；slab 是全核共享（加锁或 per-CPU）。缺页路径上分配的 <code>anon_vma</code> 一类对象走这里。</p>',9)),(e(),d(h,null,{default:o(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TYPE%5B%22%E5%AF%B9%E8%B1%A1%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20CACHE%5B%22kmem_cache%22%5D%0A%20%20CACHE%20--%3E%20SLAB%5B%22%E9%A1%B5%E5%88%87%E6%88%90%E6%A7%BD%22%5D%0A%20%20SLAB%20--%3E%20OBJ%5B%22%E5%88%86%E9%85%8D%2F%E9%87%8A%E6%94%BE%20O(1)%22%5D%0A%20%20CACHE%20--%3E%20BUD%5B%22%E7%BC%BA%E9%A1%B5%E6%97%B6%E9%97%AE%20buddy%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>slab 把「页」变成「类型化内存」，让 VFS 与网络协议栈的热点分配不再打 buddy 锁。回收时 shrinker 可以丢掉空 slab，把页还给 buddy，再给用户缺页用。不要把 slab 当成安全隔离：同页上的对象仍共享帧，越界写会破坏邻居——这是内核编程纪律，不是本课的利用指南。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>kmalloc</code> 按尺寸的通用 cache 的全部档位表。不保证实时路径无锁。下一课：当 buddy 也空了，谁去收缩 slab、页 Cache 与匿名页。</p><p>后课默认：小对象有 cache。内存压力下如何把页从 cache 与文件页里挤出来，下一课回收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>slab 在 buddy 页上为同类对象提供槽位缓存。</li><li>减少碎片与重复初始化；空 slab 可还给 buddy。</li><li>压力下的收缩是 shrinker 的缺口。</li><li>出处：Bonwick, USENIX 1994；Love, <em>LKD</em>；Bovet and Cesati, <em>ULK</em>。</li></ul>',7))])}const f=r(b,[["render",p]]);export{S as __pageData,f as default};
